insert into public.subsidieregelingen (funder_id,naam,bedrag_min,bedrag_max,deadline,deadline_datum,deadline_omschrijving,voorwaarden,status,werkgebied,aanvraaglink,algemene_beschrijving,discovered_by,verified,data_tier,source_type,access_tier,classification_reviewed,status_laatst_gecheckt)
select 'ad8c41cd-b5d1-4de3-99fa-7bc9c2d61d7b'::uuid,naam,bmin::numeric,bmax::numeric,deadline,ddat::date,domschr,voorw,status::regeling_status_type,werkgebied,link,beschr,'agent',false,'premium','premium_database','premium',true,now()
from _g where not exists (select 1 from public.subsidieregelingen s where s.funder_id='ad8c41cd-b5d1-4de3-99fa-7bc9c2d61d7b'::uuid and lower(s.naam)=lower(_g.naam));
insert into public.subsidieregeling_themas select s.id,t.id from _g join public.subsidieregelingen s on s.funder_id='ad8c41cd-b5d1-4de3-99fa-7bc9c2d61d7b'::uuid and s.naam=_g.naam cross join unnest(_g.themas) u(n) join public.themas t on t.naam=u.n on conflict do nothing;
insert into public.subsidieregeling_doelgroepen select s.id,d.id from _g join public.subsidieregelingen s on s.funder_id='ad8c41cd-b5d1-4de3-99fa-7bc9c2d61d7b'::uuid and s.naam=_g.naam cross join unnest(_g.doelgroepen) u(n) join public.doelgroepen d on d.naam=u.n on conflict do nothing;
insert into public.subsidieregeling_regios select s.id,r.id from _g join public.subsidieregelingen s on s.funder_id='ad8c41cd-b5d1-4de3-99fa-7bc9c2d61d7b'::uuid and s.naam=_g.naam join public.regios r on r.naam='Amsterdam' on conflict do nothing;
